class Solution {
public:
    int compareBitonicSums(vector<int>& nums) {
        int n = nums.size(), peak = 0;
        for (int i=1; i<n; ++i)
            if (nums[i] > nums[peak]) peak = i;
        long long a=0, b=0;
        for (int i=0; i<=peak; ++i) a+=nums[i];
        for (int i=peak; i<n; ++i) b+=nums[i];
        return a==b ? -1 : (a>b ? 0 : 1);
    }
};
